def matches(events):
    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event to check conditions
    for i in range(len(events)):
        current_event = events[i]

        # Check if the previous event overlaps with this event
        prev_event = None
        for j in range(i):
            prev_event = events[j]
            if overlap(prev_event, current_event) <= 0.5:
                break

        # If no overlapping event found, return False
        if prev_event is None:
            return False

    # Check if the last event overlaps with any other event
    for i in range(len(events)):
        current_event = events[i]
        next_event = None
        for j in range(i + 1, len(events)):
            next_event = events[j]
            if overlap(current_event, next_event) > 0.5:
                break

        # If an overlapping event is found, return False
        if next_event is not None:
            return False

    # If all checks pass, return True
    return True

