        return A['type'] == 'TURN' and B['type'] == 'DECELERATE'

    def condition2(A, B):
        return A['type'] == 'STOP' and B['type'] == 'ACCELERATE'

    def condition3(A, B):
        return A['type'] == 'DECELERATE' and B['type'] == 'ACCELERATE'

    def condition4(A, B):
        return A['type'] == 'STOP' and B['type'] == 'STOP'

    conditions = [condition1, condition2, condition3, condition4]

