def matches(events):
    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event to check if it meets the criteria
    for i in range(len(events)):
        current_event = events[i]

        # Check if the next event overlaps with this event or occurs at the same time
        for j in range(i + 1, len(events)):
            next_event = events[j]

            if current_event["type"] == "DECELERATE":
                if next_event["type"] == "TURN":
                    return True

            elif current_event["type"] == "TURN":
                if next_event["type"] == "DECELERATE":
                    return True

            # Calculate overlap between current and next event
            overlap = max(0, min(next_event['end'], current_event['end']) - max(next_event['start'], current_event['start']))

            # Check if they meet the conditions for "A then B"
            if overlap <= 0.5:
                continue

            # Check if they meet the conditions for "A while B"
            if overlap >= 0.8 * min(current_event['duration'], next_event['duration']):
                return True

    return False
```

